    if isinstance(d, dict):
        for k, v in d.items():
            if 'exchange' in str(k).lower() or 'rate' in str(k).lower() or 'canad' in str(k).lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search_dict(v, f'{path}.{k}')
